// 1. Pega os dados do NÓ ANTERIOR DIRETO (Netos: Resumos, Temas de Pesquisa e URLs)
const inputsDiretos = $input.all();

// 2. Pega os dados do NÓ "status diferente de ok1" (Pais e Filhos: Tópicos e Descrições)
let inputsConsolidados = [];
try {
  inputsConsolidados = $('status diferente de ok1').all();
} catch (error) {
  console.log("Nó 'status diferente de ok1' não retornou dados.");
}

if (inputsDiretos.length === 0 && inputsConsolidados.length === 0) {
  return [];
}

// 3. ID da Pesquisa
let idPesquisa = inputsDiretos[0]?.json?.id_pesquisa || inputsConsolidados[0]?.json?.id_pesquisa || null;

// 4. Tenta capturar o Relatório Primitivo Base
let relatorioPrimitivo = null;
try {
  const relatorioNodeData = $('verifica se é mesmo a fase relatar')?.first()?.json 
                         || $('verifica se é mesmo a fase redatar')?.first()?.json
                         || $('verifica se é mesmo a fase reatar')?.first()?.json;
  relatorioPrimitivo = relatorioNodeData?.relatorio || relatorioNodeData?.relatorio_final || null;
} catch (e) {
  // Ignora se não houver
}

// 5. CRIA A HIERARQUIA: PAI -> FILHO -> NETO
const estrutura = {};

function garantirHierarquia(passo) {
  const match = passo.match(/\d+/);
  const numeroTopico = match ? match[0] : "Outros";

  // Nível PAI (Tópico Principal)
  if (!estrutura[numeroTopico]) {
    estrutura[numeroTopico] = { 
      topico_id: numeroTopico, 
      topico_principal: "Tópico não nomeado", // Será preenchido pelo nó consolidado
      subtopicos: {} 
    };
  }

  // Nível FILHO (Subtópico)
  if (!estrutura[numeroTopico].subtopicos[passo]) {
    estrutura[numeroTopico].subtopicos[passo] = {
      passo_id: passo,
      descricao_subtopico: "", 
      consolidada: "",
      netos_pesquisas: [] // Array para guardar os Netos
    };
  }

  return {
    pai: estrutura[numeroTopico],
    filho: estrutura[numeroTopico].subtopicos[passo]
  };
}

// 5A. Preenche PAI e FILHO com dados do "status diferente de ok1"
// Como isso aqui apenas substitui variáveis (=""), não gera duplicidade
inputsConsolidados.forEach(item => {
  const json = item.json;
  if (!json.passo_id) return;

  const hierarquia = garantirHierarquia(json.passo_id);

  if (json.topico_principal) hierarquia.pai.topico_principal = json.topico_principal;
  if (json.descricao_subtopico) hierarquia.filho.descricao_subtopico = json.descricao_subtopico;
  if (json.informacao_consolidada) hierarquia.filho.consolidada = json.informacao_consolidada;
});

// 5B. Preenche os NETOS com dados do nó ANTERIOR DIRETO (COM TRAVA ANTIDUPLICIDADE)
inputsDiretos.forEach(item => {
  const json = item.json;
  if (!json.passo_id) return;

  const hierarquia = garantirHierarquia(json.passo_id);

  if (json.informacao_resumida || json.tema_pesquisa) {
    const novoResumo = json.informacao_resumida || "Sem resumo";
    const novoTema = json.tema_pesquisa || "Sem tema definido";
    const novaUrl = json.url_fonte || "URL não identificada";

    // ✅ A CORREÇÃO ESTÁ AQUI: Verifica se esse resumo exato já foi inserido neste subtópico
    const jaExiste = hierarquia.filho.netos_pesquisas.some(neto => neto.resumo === novoResumo);

    // Se não existir, aí sim ele adiciona. Se já existir, ele simplesmente descarta a cópia.
    if (!jaExiste) {
      hierarquia.filho.netos_pesquisas.push({
        tema_pesquisa: novoTema,
        resumo: novoResumo,
        url: novaUrl
      });
    }
  }
});


// 6. Monta o Prompt (Dossiê) visualmente alinhado com a hierarquia
let dossieTexto = `# INSTRUÇÃO PARA A IA REDATORA:\n`;
dossieTexto += `Sua missão é ATUALIZAR, REVISAR e EXPANDIR o **Relatório Primitivo Base** (se existente), incorporando de forma harmoniosa todas as novas evidências trazidas no **Dossiê de Pesquisa Profunda**.\n\n`;

dossieTexto += `========================================================\n`;
dossieTexto += `1. RELATÓRIO PRIMITIVO BASE (DOCUMENTO A SER ATUALIZADO)\n`;
dossieTexto += `========================================================\n`;
dossieTexto += `${relatorioPrimitivo ? relatorioPrimitivo : "(Nenhum relatório primitivo base encontrado. Gere o conteúdo do zero a partir do dossiê abaixo.)"}\n\n`;

dossieTexto += `========================================================\n`;
dossieTexto += `2. DOSSIÊ DE NOVAS DESCOBERTAS E EVIDÊNCIAS DE PESQUISA\n`;
dossieTexto += `========================================================\n`;
dossieTexto += `ID DA PESQUISA: ${idPesquisa || "N/A"}\n\n`;

const planoJson = [];
const topicosOrdenados = Object.keys(estrutura).sort((a, b) => parseInt(a) - parseInt(b));

// Renderiza a hierarquia no texto
topicosOrdenados.forEach(numTopico => {
  const pai = estrutura[numTopico];

  // Renderiza o PAI
  dossieTexto += `## 📁 PAI: ${pai.topico_principal}\n`;
  dossieTexto += `--------------------------------------------------------\n`;

  const subtopicosArray = [];
  const passosOrdenados = Object.keys(pai.subtopicos).sort((a, b) => a.localeCompare(b));

  passosOrdenados.forEach(passo => {
    const filho = pai.subtopicos[passo];

    // Renderiza o FILHO
    dossieTexto += `### 📄 FILHO [${filho.passo_id}]: ${filho.descricao_subtopico}\n\n`;

    if (filho.consolidada) {
      dossieTexto += `**Conclusão/Síntese do Auditor para este subtópico:**\n${filho.consolidada}\n\n`;
    }

    // Renderiza os NETOS
    if (filho.netos_pesquisas.length > 0) {
      dossieTexto += `**🔬 NETOS (Pesquisas Individuais Realizadas):**\n`;
      filho.netos_pesquisas.forEach((neto, index) => {
        dossieTexto += `\n> **Pesquisa ${index + 1} | Tema:** ${neto.tema_pesquisa}\n`;
        dossieTexto += `> **Fonte:** ${neto.url}\n`;
        dossieTexto += `> **Resumo:** ${neto.resumo}\n`;
      });
      dossieTexto += `\n`;
    }

    dossieTexto += `--------------------------------------------------------\n`;

    // Monta a estrutura de dados limpa (JSON)
    subtopicosArray.push({
      passo: filho.passo_id,
      descricao_subtopico: filho.descricao_subtopico,
      conclusao_auditor: filho.consolidada,
      pesquisas_realizadas: filho.netos_pesquisas // Aqui estão os netos limpos e sem duplicatas!
    });
  });

  planoJson.push({
    topico_principal: pai.topico_principal,
    subtopicos: subtopicosArray
  });

  dossieTexto += `\n`;
});

// 7. Retorna 1 ÚNICO item empacotado para o LLM Redator
return [{
  json: {
    id_pesquisa: idPesquisa,
    relatorio_primitivo_base: relatorioPrimitivo, 
    plano_json_estruturado: planoJson, 
    dossie_pronto_para_ia: dossieTexto 
  }
}];

const grupos = {};

// 1. Agrupa os itens pelo id_pesquisa e faz a contagem
for (const item of $input.all()) {
  const id = item.json.id_pesquisa; // Ajuste se o nome da sua coluna de ID for diferente

  if (!grupos[id]) {
    grupos[id] = { total: 0, concluidos: 0 };
  }

  grupos[id].total += 1;

  // Ajuste 'status' e 'ok' para os nomes exatos que vêm do seu banco
  if (item.json.status === 'ok') { 
    grupos[id].concluidos += 1;
  }
}

const output = [];

// 2. Verifica se a pesquisa está 100% pronta
for (const id in grupos) {
  // Se o total de itens for IGUAL ao total de itens 'ok', a pesquisa acabou.
  if (grupos[id].total === grupos[id].concluidos) {
    output.push({
      json: {
        id_pesquisa: id
      }
    });
  }
}

// 3. Devolve para o fluxo. Se faltar algum item, ele retorna vazio e o fluxo PARA aqui.
return output;

// 1. Pega os 13 subtópicos oficiais da status_pesquisa
const subtopicosOriginais = $('obtem items com status auditar').all();

if (subtopicosOriginais.length === 0) {
  return [];
}

// 2. Pega as linhas garimpadas da deep_research (se houver)
const linhasBrutas = $input.all();

// 3. INICIALIZA O AGRUPADOR COM TODOS OS 13 SUBTÓPICOS OFICIAIS
const dadosAgrupados = {};

subtopicosOriginais.forEach(item => {
  const pIdRaw = item.json.passo_id;
  if (pIdRaw) {
    const match = String(pIdRaw).toLowerCase().match(/\d+[a-z]/);
    const key = match ? match[0] : String(pIdRaw).trim().toLowerCase();

    dadosAgrupados[key] = {
      passo_id: key,
      id_pesquisa: item.json.id_pesquisa || null,
      topico_principal: item.json.topico_principal || "",
      descricao: item.json.descricao_subtopico || "Descrição não encontrada",
      status: item.json.status || "",
      informacoes: []
    };
  }
});

// 4. Popula as informações garimpadas vindas da deep_research nas chaves já existentes
linhasBrutas.forEach(item => {
  const json = item.json;
  const rawRef = json.passo_id || json.topico_referencia || "";
  const match = String(rawRef).toLowerCase().match(/\d+[a-z]/);
  if (!match) return;

  const ref = match[0];

  // Adiciona a informação garimpada ao subtópico correspondente
  if (dadosAgrupados[ref] && json.informacao_resumida) {
    dadosAgrupados[ref].informacoes.push(json.informacao_resumida);
  }
});

// 5. Ordena as chaves dos subtópicos (1a, 1b, 2a, 3a...)
const refsOrdenadas = Object.keys(dadosAgrupados).sort((a, b) => {
  const matchA = a.match(/\d+/);
  const matchB = b.match(/\d+/);

  const numA = matchA ? parseInt(matchA[0]) : 0;
  const numB = matchB ? parseInt(matchB[0]) : 0;

  if (numA !== numB) return numA - numB;
  return a.localeCompare(b);
});

// 6. Monta a saída garantindo QUE TODOS OS 13 SUBTÓPICOS VÃO PARA O AUDITOR
const outputItems = refsOrdenadas.map(ref => {
  const sub = dadosAgrupados[ref];

  let infoFormatada = "";
  if (sub.informacoes.length > 0) {
    const infoUnicas = [...new Set(sub.informacoes)];
    infoFormatada = infoUnicas.map(info => `- ${info}`).join('\n');
  } else {
    infoFormatada = "- Nenhuma informação foi garimpada para este tópico.";
  }

  return {
    json: {
      id_pesquisa: sub.id_pesquisa,
      topico_principal: sub.topico_principal,
      passo_id: sub.passo_id,
      subtopico: `(${sub.passo_id}) ${sub.descricao}`,
      status_atual: sub.status,
      informacao_resumida_desse_subtopico: infoFormatada
    }
  };
});

return outputItems;

// 1. Pega todos os itens da entrada (linhas da status_pesquisa)
const items = $input.all();

if (items.length === 0) {
  return [];
}

// 2. Verifica se 100% dos itens possuem exatamente o status "auditar" E não estão processando
const todosProntosParaAuditar = items.every(item => 
  item.json.status === 'ok' && 
  item.json.Processando === false
);

// 3. Se faltar qualquer um (ex: status 'pendente', ou Processando: true), encerra em silêncio (retorna array vazio)
if (!todosProntosParaAuditar) {
  return [];
}

// 4. Se TODOS estiverem como "auditar" e Processando false, pega o id_pesquisa do primeiro item
const idPesquisa = items[0].json.id_pesquisa;

// 5. Retorna UM ÚNICO ITEM contendo o id_pesquisa para liberar os próximos nós
return [
  {
    json: {
      id_pesquisa: idPesquisa,
      total_subtopicos: items.length,
      status_geral: "todos_prontos_para_auditar"
    }
  }
];

// 1. Pega os itens de entrada do nó atual (a resposta da Jina)
const items = $input.all();
const resultadosLimpos = [];

// 2. Resgata a query exata do nó "Google Search Scrapper"
// Usando a sintaxe oficial do n8n para referenciar nós anteriores
const queryOriginal = $('Google Search Scrapper').first().json.body.queries || "";

for (const item of items) {
  // A Jina Search devolve os resultados dentro da array 'data'
  const searchResults = item.json.data || [];

  if (Array.isArray(searchResults)) {
    for (const result of searchResults) {

      // Pula páginas que falharam no scraping (status 400+, 429, 403, etc.)
      if (result.httpStatus && result.httpStatus >= 400) {
        continue;
      }

      let rawMarkdown = result.content || "";

      if (rawMarkdown) {
        // --- A FAXINA (REGEX) ---

        // A. Remove completamente as tags de imagem em Markdown: ![Imagem 1](https://url...)
        rawMarkdown = rawMarkdown.replace(/!\[.*?\]\(.*?\)/g, '');

        // B. Remove os links em Markdown, MAS MANTÉM O TEXTO.
        // Exemplo: [Facebook](https://fb.com) vira apenas "Facebook"
        rawMarkdown = rawMarkdown.replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1');

        // C. Remove links puros "http..." jogados no meio do texto
        rawMarkdown = rawMarkdown.replace(/(https?:\/\/[^\s]+)/g, '');

        // D. Limpa marcas/frases de cookies e popups conhecidos
        const lixoComum = /Gerir opções|Aceitar Negar|Gerir serviços|Estatísticas|Marketing|Preferências/gi;
        rawMarkdown = rawMarkdown.replace(lixoComum, '');

        // E. Remove linhas vazias excessivas (3 ou mais sobram apenas 2)
        rawMarkdown = rawMarkdown.replace(/\n{3,}/g, '\n\n');
      }

      // Garante que só inclui resultados com conteúdo textual real
      if (rawMarkdown.trim().length > 0) {
        resultadosLimpos.push({
          json: {
            query: queryOriginal,
            title: result.title || "",
            url: result.url || "",
            texto_limpo: rawMarkdown.trim()
          }
        });
      }
    }
  }
}

return resultadosLimpos;

// 1. Pega todos os itens da entrada (linhas da status_pesquisa)
const items = $input.all();

if (items.length === 0) {
  return [];
}

// 2. Verifica se 100% dos itens possuem o status "auditar" OU "ok" E não estão processando
const todosProntos = items.every(item => 
  ['auditar', 'ok'].includes(item.json.status) && 
  item.json.Processando === false
);

// 3. Se faltar qualquer um (ex: status 'pendente', ou Processando: true), encerra em silêncio (retorna array vazio)
if (!todosProntos) {
  return [];
}

// 4. Se TODOS estiverem validados e com Processando false, pega o id_pesquisa do primeiro item
const idPesquisa = items[0].json.id_pesquisa;

// 5. Retorna UM ÚNICO ITEM contendo o id_pesquisa para liberar os próximos nós
return [
  {
    json: {
      id_pesquisa: idPesquisa,
      total_subtopicos: items.length,
      status_geral: "todos_prontos"
    }
  }
];

